def point_in_polygon(r, c, vertices):
    """Ray casting algorithm for point in polygon"""
    n = len(vertices)
    inside = False
    for i in range(n):
        j = (i + 1) % n
        # Check if ray from point to right crosses edge
        if ((vertices[i][1] > c) != (vertices[j][1] > c)):
            # Find edge y value at point's x
            edge_y = vertices[i][1] + (c - vertices[i][1]) * (vertices[j][0] - vertices[i][0]) / (vertices[j][1] - vertices[i][1]) if vertices[j][1] != vertices[i][1] else vertices[i][1]
            if r < edge_y:
                inside = not inside
    return inside

