def bresenham_line(r1, c1, r2, c2):
    """Draw a line from (r1, c1) to (r2, c2) using Bresenham's algorithm"""
    points = []
    dr = r2 - r1
    dc = c2 - c1

    if abs(dr) > abs(dc):
        # Steeper line - iterate over rows
        step = 1 if dr > 0 else -1
        if dr == 0:
            for c in range(min(c1, c2), max(c1, c2) + 1):
                points.append((r1, c))
        else:
            for r in range(r1, r2 + step, step):
                # Calculate interpolated column
                t = (r - r1) / abs(dr)
                c_interpolated = c1 + dc * t
                c_rounded = round(c_interpolated)
                points.append((r, c_rounded))
    elif abs(dc) > abs(dr):
        # Flatter line - iterate over columns
        step = 1 if dc > 0 else -1
        if dc == 0:
            for r in range(min(r1, r2), max(r1, r2) + 1):
                points.append((r, c1))
        else:
            for c in range(c1, c2 + step, step):
                t = (c - c1) / abs(dc)
                r_interpolated = r1 + dr * t
                r_rounded = round(r_interpolated)
                points.append((r_rounded, c))
    else:
        # Same magnitude, iterate carefully
        for t in range(max(abs(dr), abs(dc)) + 1):
            r_interpolated = r1 + dr * t / max(abs(dr), abs(dc))
            c_interpolated = c1 + dc * t / max(abs(dr), abs(dc))
            points.append((round(r_interpolated), round(c_interpolated)))

    return set(points)

