def convex_hull_order(vertices):
    hull = vertices[:]
    for i in range(1, len(vertices) - 1):
        c = (hull[i][0] - hull[0][0]) * (hull[i+1][1] - hull[0][1]) - \
             (hull[i][1] - hull[0][1]) * (hull[i+1][0] - hull[0][0])
        if c < 0:
            hull[i], hull[i+1] = hull[i+1], hull[i]
    return hull

